"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Phone, Settings, Play, RefreshCw, Mic } from "lucide-react";
import AssistantConfig from "@/components/dashboard/AssistantConfig";
import LiveCallMonitor from '@/components/dashboard/LiveCallMonitor';
import { vapiApi } from "@/lib/api-endpoints";

export default function VoiceAgentControlCenter() {
  const [activeTab, setActiveTab] = useState("agent");
  const [assistant, setAssistant] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    try {
      setLoading(true);
      const data = await vapiApi.getMyAssistant();
      setAssistant(data);
    } catch (error) {
      console.error("Failed to load assistant:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">AI Receptionist Control Center</h1>
          <p className="text-muted-foreground mt-1">
            Configure your Vapi-powered AI assistant
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={() => window.location.href = "/dashboard/voice-agent/test"}>
            <Play className="w-4 h-4 mr-2" />
            Test Call
          </Button>
          <Button onClick={loadData} variant="ghost">
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="agent">
            <Mic className="w-4 h-4 mr-2" />
            Agent Configuration
          </TabsTrigger>
          {/* Future tabs: Call Logs, Phone Numbers */}
        </TabsList>

        <TabsContent value="agent" className="mt-6">
          <div className="grid gap-6 md:grid-cols-2">
            <div className="space-y-6">
              <AssistantConfig />
            </div>
            <div className="space-y-6">
              <LiveCallMonitor />

              <Card>
                <CardHeader>
                  <CardTitle>Assistant Status</CardTitle>
                  <CardDescription>Current deployment information</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center bg-gray-50 p-3 rounded-lg">
                      <span className="text-sm font-medium">Status</span>
                      <Badge variant={(assistant && assistant.assistant_id) ? "default" : "destructive"}>
                        {(assistant && assistant.assistant_id) ? 'Active' : 'Not Configured'}
                      </Badge>
                    </div>

                    <div className="flex justify-between items-center bg-gray-50 p-3 rounded-lg">
                      <span className="text-sm font-medium">Assistant ID</span>
                      <span className="text-xs font-mono text-gray-500">
                        {assistant?.assistant_id || 'N/A'}
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}
